(()=>{const launcher=document.createElement('button'),dialog=document.createElement('dialog');launcher.className='feedback-launcher';launcher.type='button';launcher.textContent='Send feedback';dialog.className='feedback-dialog';dialog.innerHTML='<div class="feedback-shell"><button class="feedback-close" type="button" aria-label="Close feedback">&times;</button><div id="feedbackFormView"><span class="kicker">Help shape Trades</span><h2>Share feedback.</h2><p>Ideas, problems, and honest reactions go directly to the Trades owner.</p><form id="feedbackForm"><label><span>What kind of feedback?</span><select name="category"><option value="idea">Feature idea</option><option value="bug">Something is not working</option><option value="usability">Hard to use or understand</option><option value="question">Question</option><option value="other">Other</option></select></label><label><span>Short title</span><input name="title" maxlength="180" placeholder="What should we know?"></label><label><span>Details</span><textarea name="message" rows="6" maxlength="3000" required placeholder="Tell us what happened or what would make Trades better."></textarea></label><button class="button button-orange button-full" type="submit">Send to Trades</button></form></div><div class="feedback-result" id="feedbackResult" hidden><strong>Feedback received.</strong><span>Thanks for helping make Trades better.</span><button class="button button-dark" type="button">Done</button></div></div>';document.body.append(launcher,dialog);const form=dialog.querySelector('#feedbackForm'),formView=dialog.querySelector('#feedbackFormView'),result=dialog.querySelector('#feedbackResult');launcher.onclick=()=>{formView.hidden=false;result.hidden=true;dialog.showModal()};dialog.querySelector('.feedback-close').onclick=()=>dialog.close();result.querySelector('button').onclick=()=>dialog.close();form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]'),data=Object.fromEntries(new FormData(form));button.disabled=true;button.textContent='Sending...';try{const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,page:location.pathname})}),body=await response.json();if(!response.ok)throw Error(body.error||'Feedback could not be sent.');form.reset();formView.hidden=true;result.hidden=false}catch(error){alert(error.message)}finally{button.disabled=false;button.textContent='Send to Trades'}}})();
